sys_variable_value.value:
(function execute(inputs, outputs) {
    var gr = new GlideRecord('sys_flow_data');
    gr.initialize();

    gr.setValue('definition', inputs.definition);
    gr.setValue('state', inputs.state);
    gr.setValue('assigned_to', inputs.assigned_to);
    gr.setValue('assignment_group', inputs.assignment_group);
    
    // Handle null or empty playbook_context gracefully
    if (inputs.playbook_context && inputs.playbook_context.getUniqueValue) {
        gr.setValue('playbook_context', inputs.playbook_context.getUniqueValue());
    }
    gr.setValue('activity_id', inputs.activity_id);

    var newSysId = gr.insert();

    if (newSysId) {
        outputs.sys_flow_data_record = gr;
    } else {
        gs.warn('Failed to insert new sys_flow_data record');
    }
})(inputs, outputs);

