sys_variable_value.value:
(function execute(inputs, outputs) {
    outputs.out_var = {
        flowInternalFieldType: "glide_var",
        record: {
            table: "sys_flow_data",
            sysId: inputs.record_id
        },
        glideVarElementField: "vars"
    }
})(inputs, outputs);

